    static void wordleJava(){
        header("WORDLE JAVA");
        String[] bank={"classe","objeto","metodo","array","string","stream","lambda","thread","enum","debug"};
        String secret=random(bank); Set<Character>known=new HashSet<>();
        for(int turn=1;turn<=6;turn++){
            String g=ask("Tentativa "+turn+": ").trim().toLowerCase(Locale.ROOT);
            if(g.length()!=secret.length()){System.out.println("Use "+secret.length()+" letras.");turn--;continue;}
            StringBuilder clue=new StringBuilder();
            for(int i=0;i<g.length();i++){
                char c=g.charAt(i); known.add(c);
                if(secret.charAt(i)==c)clue.append('[').append(c).append(']');
                else if(secret.indexOf(c)>=0)clue.append('(').append(c).append(')');
                else clue.append(' ').append(c).append(' ');
            }
            System.out.println(clue);
            if(g.equals(secret)){PLAYER.win(75,30);System.out.println(GREEN+"Palavra descoberta!"+RESET);pause();return;}
        }
        PLAYER.lose();System.out.println(RED+"Era "+secret+RESET);pause();
    }

    static void connectFour(){
        header("CONNECT 4");
        char[][] b=new char[6][7];for(char[]r:b)Arrays.fill(r,'.');
        for(int turn=0;turn<42;turn++){
            printConnect(b);
            int col;
            if(turn%2==0){col=askInt("Coluna 1-7: ",1,7)-1;}else{col=RNG.nextInt(7);}
            int row=-1;for(int r=5;r>=0;r--)if(b[r][col]=='.'){row=r;break;}
            if(row<0){if(turn%2==0){System.out.println("Coluna cheia.");turn--;}continue;}
            b[row][col]=turn%2==0?'X':'O';
            if(connectWin(b,b[row][col])){
                printConnect(b);
                if(b[row][col]=='X'){PLAYER.win(80,35);System.out.println(GREEN+"Você conectou 4!"+RESET);}else{PLAYER.lose();System.out.println(RED+"CPU conectou 4."+RESET);}pause();return;
            }
        }
        System.out.println(YELLOW+"Empate."+RESET);pause();
    }
    static void printConnect(char[][]b){for(char[]r:b){for(char c:r)System.out.print(c+" ");System.out.println();}System.out.println("1 2 3 4 5 6 7");}
    static boolean connectWin(char[][]b,char c){int R=b.length,C=b[0].length;int[][]d={{1,0},{0,1},{1,1},{1,-1}};for(int r=0;r<R;r++)for(int col=0;col<C;col++)if(b[r][col]==c)for(int[]v:d){int cnt=1;for(int k=1;k<4;k++){int rr=r+v[0]*k,cc=col+v[1]*k;if(rr<0||rr>=R||cc<0||cc>=C||b[rr][cc]!=c)break;cnt++;}if(cnt==4)return true;}return false;}

    static void minesweeper(){
        header("CAMPO MINADO"); int n=6,mines=6;boolean[][]m=new boolean[n][n],open=new boolean[n][n];
        int placed=0;while(placed<mines){int r=RNG.nextInt(n),c=RNG.nextInt(n);if(!m[r][c]){m[r][c]=true;placed++;}}
        int safe=n*n-mines,opened=0;
        while(true){printMine(m,open);String raw=ask("Linha coluna (ex: 2 3) ou Q: ").trim();if(raw.equalsIgnoreCase("q")){PLAYER.lose();pause();return;}String[]p=raw.split("\\s+");if(p.length!=2)continue;try{int r=Integer.parseInt(p[0])-1,c=Integer.parseInt(p[1])-1;if(r<0||c<0||r>=n||c>=n)continue;if(open[r][c])continue;if(m[r][c]){printMine(m,open);PLAYER.lose();System.out.println(RED+"BOOM!"+RESET);pause();return;}open[r][c]=true;opened++;if(opened>=safe){PLAYER.win(100,45);System.out.println(GREEN+"Campo limpo!"+RESET);pause();return;}}catch(Exception ignored){}}
    }
    static void printMine(boolean[][]m,boolean[][]o){for(int r=0;r<m.length;r++){for(int c=0;c<m.length;c++){if(o[r][c])System.out.print(numberAround(m,r,c)+" ");else System.out.print("# ");}System.out.println();}}
    static int numberAround(boolean[][]m,int r,int c){int x=0;for(int dr=-1;dr<=1;dr++)for(int dc=-1;dc<=1;dc++){int rr=r+dr,cc=c+dc;if(rr>=0&&cc>=0&&rr<m.length&&cc<m.length&&m[rr][cc])x++;}return x;}

    static void mastermind(){
        header("MASTERMIND");String secret=String.format("%04d",RNG.nextInt(10000));
        for(int t=1;t<=10;t++){String g=ask("Tentativa "+t+": ").trim();if(!g.matches("\\d{4}")){System.out.println("4 dígitos.");t--;continue;}if(g.equals(secret)){PLAYER.win(100,45);System.out.println(GREEN+"MASTER!"+RESET);pause();return;}int exact=0,present=0;for(int i=0;i<4;i++){if(g.charAt(i)==secret.charAt(i))exact++;if(secret.indexOf(g.charAt(i))>=0)present++;}System.out.println("Exatos="+exact+" Presentes="+present);}
        PLAYER.lose();System.out.println(RED+"Código: "+secret+RESET);pause();
    }

    static void caesarCipher(){
        header("CIFRA DE CÉSAR");String[]phrases={"java e divertido","aprenda um conceito por vez","objetos possuem estado","metodos organizam codigo"};String p=random(phrases);int shift=1+RNG.nextInt(9);String enc=caesar(p,shift);System.out.println("Texto cifrado: "+MAGENTA+enc+RESET);System.out.println("Deslocamento: "+shift);String a=ask("Decodificado: ");if(a.equals(p)){PLAYER.win(70,28);System.out.println(GREEN+"Decodificação correta!"+RESET);}else{PLAYER.lose();System.out.println("Era: "+p);}pause();
    }
    static String caesar(String s,int sh){StringBuilder b=new StringBuilder();for(char c:s.toCharArray()){if(c>='a'&&c<='z')b.append((char)('a'+(c-'a'+sh)%26));else b.append(c);}return b.toString();}

    static void binaryDuel(){
        header("DUELO BINÁRIO");int score=0;for(int i=0;i<8;i++){int n=RNG.nextInt(32),ans=askInt(n+" em decimal. Converta para binário: ",0,Integer.MAX_VALUE);if(ans==Integer.parseInt(Integer.toBinaryString(n))){score++;System.out.println(GREEN+"certo"+RESET);}else System.out.println("Dica: "+Integer.toBinaryString(n));}if(score>=6)PLAYER.win(80,32);else PLAYER.lose();System.out.println("Score "+score+"/8");pause();
    }

    static void sortingRace(){
        header("SORTING RACE");int[]a=new int[9];for(int i=0;i<a.length;i++)a[i]=RNG.nextInt(50);System.out.println("Ordene: "+Arrays.toString(a));String raw=ask("Resultado separado por espaços: ");try{String[]p=raw.trim().split("\\s+");int[]u=Arrays.stream(p).mapToInt(Integer::parseInt).toArray();int[]e=a.clone();Arrays.sort(e);if(Arrays.equals(u,e)){PLAYER.win(80,30);System.out.println(GREEN+"Ordenação correta!"+RESET);}else{PLAYER.lose();System.out.println("Correto: "+Arrays.toString(e));}}catch(Exception e){PLAYER.lose();System.out.println("Entrada inválida.");}pause();
    }

    static void stackChallenge(){
        header("STACK CHALLENGE");Deque<Integer>s=new ArrayDeque<>();for(int i=0;i<6;i++){int v=10+RNG.nextInt(90);s.push(v);System.out.println("PUSH "+v);}System.out.println("Agora adivinhe os valores POP na ordem reversa.");int ok=0;while(!s.isEmpty()){int expected=s.peek(),u=askInt("POP: ",Integer.MIN_VALUE,Integer.MAX_VALUE);int actual=s.pop();if(u==expected)ok++;System.out.println("Saiu "+actual);}if(ok==6){PLAYER.win(75,28);System.out.println(GREEN+"LIFO dominado!"+RESET);}else PLAYER.lose();pause();
    }

    static void memoryPairs(){
        header("MEMORY PAIRS");List<String>cards=new ArrayList<>();for(char c='A';c<='F';c++){cards.add(""+c);cards.add(""+c);}Collections.shuffle(cards);Set<Integer>found=new HashSet<>();int pairs=0;
        while(pairs<6){for(int i=0;i<cards.size();i++)System.out.print(found.contains(i)?cards.get(i)+" ":"? ");System.out.println();int a=askInt("Primeira posição 1-12: ",1,12)-1,b=askInt("Segunda: ",1,12)-1;if(a==b||found.contains(a)||found.contains(b))continue;System.out.println(cards.get(a)+" "+cards.get(b));if(cards.get(a).equals(cards.get(b))){found.add(a);found.add(b);pairs++;System.out.println(GREEN+"Par!"+RESET);}else System.out.println(RED+"Não combinou."+RESET);}
        PLAYER.win(110,50);System.out.println(GREEN+"Todos os pares!"+RESET);pause();
    }

