    static void countdownMath(){
        header("COUNTDOWN MATH");int target=100+RNG.nextInt(200),a=2+RNG.nextInt(9),b=2+RNG.nextInt(9),c=2+RNG.nextInt(9);System.out.println("Números: "+a+", "+b+", "+c);System.out.println("Alvo aproximado/exato: "+target);String expr=ask("Crie uma expressão usando os três: ");try{int value=evaluateSimple(expr);System.out.println("Resultado calculado: "+value);if(value==target){PLAYER.win(120,55);System.out.println(GREEN+"Alvo atingido!"+RESET);}else PLAYER.lose();}catch(Exception e){PLAYER.lose();System.out.println("Não consegui interpretar a expressão.");}pause();
    }
    static int evaluateSimple(String e){String[]p=e.trim().split("\\s+");if(p.length==3){int x=Integer.parseInt(p[0]),z=Integer.parseInt(p[2]);return p[1].equals("+")?x+z:p[1].equals("-")?x-z:p[1].equals("*")?x*z:x/z;}if(p.length==5){int x=evaluateSimple(String.join(" ",Arrays.copyOfRange(p,0,3))),z=Integer.parseInt(p[4]);return p[3].equals("+")?x+z:p[3].equals("-")?x-z:p[3].equals("*")?x*z:x/z;}throw new IllegalArgumentException();}

    static void fishingRng(){
        header("PESCA RNG");String[]loot={"peixe pequeno","peixe dourado","bota lendária","tesouro","alga","peixe raro","baú misterioso"};int catches=5,best=0;for(int i=0;i<catches;i++){int roll=RNG.nextInt(100);String item=roll<5?"tesouro":roll<15?"peixe raro":random(loot);int value=5+RNG.nextInt(30);best=Math.max(best,value);System.out.println("Pesca "+(i+1)+": "+item+" (valor "+value+")");PLAYER.coins+=value/5;}if(best>=25)PLAYER.win(70,20);else PLAYER.win(35,10);pause();
    }

